j:jelly.g2:evaluate:
  var tz_style = "";
  if (!gs.getUser().hasRoles())
	  tz_style = "display:none";

  var cl = new GlideChoiceList();
  cl.addNone();
  var themes = new GlideRecord('sys_ui_theme');
  var qc1 = themes.addQuery('sys_id', gs.getSession().getProperty('glide.css.theme'));
  if (GlideMobileExtensions.getDeviceType() == 'doctype')
	  qc1.addOrCondition('device', 'doctype');
  else
	  qc1.addOrCondition('device', 'browser');
  themes.addActiveQuery();
  themes.orderBy('name');
  themes.query();
  while (themes.next())
	 cl.add(themes.sys_id + '', themes.name + '');

  if (1 >= cl.getSize())
	 tz_style = "display:none";

j:jelly.span:
${gs.getMessage("Theme")}:$[SP]








	var theme_changer;
	addLoadEvent(function() { theme_change = new ThemeChanger("theme_changer") } );
